var e={"vmode.on":`Mode vocal : parlez à Harness à voix haute`,"vmode.off":`Raccrocher`,"vmode.connecting":`Connexion`,"vmode.listening":`Je vous écoute`,"vmode.hearing":`Je vous entends`,"vmode.thinking":`Réflexion`,"vmode.speaking":`Harness parle`,"vmode.paused":`En pause`,"vmode.working":`Claude travaille`,"vmode.tapSkip":`Touchez pour le faire taire`,"vmode.you":`Vous`,"vmode.voice":`Harness`,"vmode.notReady":`Réglez d'abord le mode vocal (Réglages → Voix)`,"vmode.failed":`Mode vocal`,"vmode.card":`Mode vocal`,"vmode.cardDesc":`Parlez à Harness à voix haute : une voix vous répond, confie le vrai travail à la session avec vos propres mots (le même Claude, les mêmes fichiers et outils) et vous dit le résultat. Bouton dans la barre d'une session.`,"vmode.set.local":`Sur ce serveur`,"vmode.set.localDesc":`Gratuit et privé : la transcription de Réglages → Voix, un modèle Claude comme voix, Piper pour parler.`,"vmode.set.cloud":`Cloud (temps réel)`,"vmode.set.cloudDesc":`Un modèle vocal temps réel d'OpenAI ou de Gemini : répond en moins d'une seconde, naturel, on peut lui couper la parole. Environ 1 à 5 centimes la minute, sur votre clé ; l'audio part chez ce fournisseur.`,"vmode.set.ready":`Prêt`,"vmode.set.needStt":`Activez les messages vocaux ci-dessus (n'importe quel moteur) : la voix locale s'en sert pour vous entendre.`,"vmode.set.needTts":`La voix locale n'est pas installée`,"vmode.set.needTtsDesc":`Piper et deux voix (français, anglais) : environ 150 Mo, une minute.`,"vmode.set.install":`Installer`,"vmode.set.talker":`Modèle de la voix`,"vmode.set.silence":`Pause avant la fin de votre phrase`,"vmode.set.silenceDesc":`Le silence au bout duquel la voix considère que vous avez fini de parler.`,"vmode.set.talkerDesc":`Il parle avec vous et décide quand la session travaille : Sonnet décide mieux, Haiku répond plus vite.`,"vmode.set.haiku":`Haiku (rapide)`,"vmode.set.sonnet":`Sonnet (recommandé)`,"vmode.set.voice":`Voix`,"vmode.set.localVoiceDesc":`Utilisée quand la voix parle sa langue (une autre langue a sa propre voix). ↓ = téléchargée quand on la choisit.`,"vmode.set.auto":`Automatique`,"vmode.set.speed":`Vitesse`,"vmode.set.speedDesc":`La vitesse à laquelle parle la voix locale.`,"vmode.set.speed1":`Posée`,"vmode.set.speed115":`Normale`,"vmode.set.speed13":`Rapide`,"vmode.set.speed145":`Très rapide`,"vmode.set.chooseProvider":`Vous avez une clé OpenAI et une clé Gemini : choisissez celle à utiliser.`,"vmode.set.keyFound":`Clé trouvée`,"vmode.set.noKey":`Pas de clé`,"vmode.set.openaiDesc":`OpenAI Realtime en WebRTC. Voix très naturelles.`,"vmode.set.geminiDesc":`Gemini Live. Le moins cher, très bon dans beaucoup de langues.`,"vmode.set.key":`Clé`,"vmode.set.keyDesc":`Gardée dans le coffre ; le navigateur ne reçoit qu'un jeton valable pour un appel.`,"vmode.set.keyChoose":`Plusieurs clés trouvées dans le coffre : choisissez celle à utiliser.`,"vmode.set.keyPick":`Choisir une clé`,"vmode.set.model":`Modèle`,"vmode.set.modelDesc":`À changer quand le fournisseur en sort un nouveau.`,"vmode.set.privacy":`Votre clé ne quitte jamais ce serveur : chaque appel reçoit un jeton temporaire avec les consignes verrouillées.`};export{e as default};